import{_ as a,o as e,c as r,a6 as o}from"./chunks/framework.BBIckNDn.js";const g=JSON.parse('{"title":"手動メモリ管理と GC","description":"","frontmatter":{"title":"手動メモリ管理と GC","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"本論は第7部: GCとの違いで詳述済み。このページはUnity開発者の視点からの要点整理と実践対応表です。 C++のメモリ管理は「毎回deleteを手で書く」ではありません。現代C++は:"}},"headers":[],"relativePath":"languages/csharp/memory-management-vs-gc.md","filePath":"languages/csharp/memory-management-vs-gc.md"}'),s={name:"languages/csharp/memory-management-vs-gc.md"};function n(l,t,d,i,h,m){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="手動メモリ管理と-gc" tabindex="-1">手動メモリ管理と GC <a class="header-anchor" href="#手動メモリ管理と-gc" aria-label="Permalink to &quot;手動メモリ管理と GC&quot;">​</a></h1><p>本論は<a href="/study/runtime/memory/gc-and-csharp-comparison.html">第7部: GCとの違い</a>で詳述済み。このページはUnity開発者の視点からの<strong>要点整理と実践対応表</strong>です。</p><h2 id="「手動」という誤解を先に解く" tabindex="-1">「手動」という誤解を先に解く <a class="header-anchor" href="#「手動」という誤解を先に解く" aria-label="Permalink to &quot;「手動」という誤解を先に解く&quot;">​</a></h2><p>C++のメモリ管理は「毎回deleteを手で書く」ではありません。現代C++は:</p><ol><li><strong>値とスコープ</strong>(そもそもヒープを使わない)— 第一選択</li><li><strong>RAII+スマートポインタ</strong>(解放は型が自動でやる)— ヒープが要るとき</li><li><strong>生のnew/delete</strong> — RAII部品の内部実装のみ(ゲームロジックには現れない)</li></ol><p>「手動」なのは<strong>解放のタイミングと所有権の設計</strong>であって、解放作業そのものではない——ここがC#経験者の第一の発見です。</p><h2 id="実践対応表-unityでの習慣-→-c-での対応" tabindex="-1">実践対応表(Unityでの習慣 → C++での対応) <a class="header-anchor" href="#実践対応表-unityでの習慣-→-c-での対応" aria-label="Permalink to &quot;実践対応表(Unityでの習慣 → C++での対応)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unityでの習慣</th><th>C++での対応</th><th>参照</th></tr></thead><tbody><tr><td>GC Allocをプロファイラで監視</td><td>ヒープ確保をプロファイラ/自作カウンタで監視</td><td><a href="/study/runtime/memory/allocators-and-pools.html">アロケータ</a></td></tr><tr><td>Update内でnewしない</td><td>フレーム内のヒープ確保を避ける(値・再利用・アリーナ)</td><td>同上</td></tr><tr><td>オブジェクトプール</td><td>Object Pool(同じ)+ memory pool</td><td><a href="/study/game/patterns/object-pool.html">Object Pool</a></td></tr><tr><td>struct/NativeArrayで管理外に置く</td><td>それが<strong>通常の状態</strong>(全部が管理外)</td><td><a href="/study/languages/csharp/pointers-references-value-semantics.html">値セマンティクス</a></td></tr><tr><td>参照をnullにしてGCに任せる</td><td>所有者の破棄=即解放。非所有参照の無効化は<strong>自分の問題</strong></td><td><a href="/study/runtime/memory/ownership-and-borrowing.html">所有権</a></td></tr><tr><td>Destroy(gameObject)+MissingReference例外</td><td>delete+dangling(<strong>例外は出ない</strong>。UB)</td><td><a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a></td></tr><tr><td>WeakReference(ほぼ使わない)</td><td>weak_ptr/世代ハンドル(<strong>日常の道具</strong>)</td><td><a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a></td></tr></tbody></table><h2 id="思考の転換ポイント3つ" tabindex="-1">思考の転換ポイント3つ <a class="header-anchor" href="#思考の転換ポイント3つ" aria-label="Permalink to &quot;思考の転換ポイント3つ&quot;">​</a></h2><ol><li><strong>「確保コスト」の意識が逆転する</strong>: C#では確保は速く回収が痛い。C++では汎用確保がそこそこ重く、解放は決定的。→ C++では「フレーム中の確保そのもの」を設計で消す(事前確保・プール・アリーナ)</li><li><strong>「参照を持つ」ことの意味が逆転する</strong>: C#の参照は延命保証つき。C++の参照・ポインタは<strong>ただの矢印</strong>(寿命は別管理)。「誰が所有者か」を先に決めるのがC++の設計手順</li><li><strong>リークの形が変わる</strong>: C#のリークは「参照の残留」(イベント購読・static)。C++のリークは「所有者の不在」(生new・循環shared_ptr)。<strong>どちらも設計の失敗</strong>であり、GCはそれを免除しない</li></ol><h2 id="実務でのハイブリッド感覚" tabindex="-1">実務でのハイブリッド感覚 <a class="header-anchor" href="#実務でのハイブリッド感覚" aria-label="Permalink to &quot;実務でのハイブリッド感覚&quot;">​</a></h2><ul><li>UnityでもDOTS/NativeArrayを使えば「手動管理の世界」に半分入っていた(Allocator.Temp/Persistent、Dispose必須)——あれがC++の日常</li><li>UEに行くと「C++なのにUObjectはGC管理」という逆ハイブリッド(→ <a href="/study/game/unreal/gc-and-object-pointers.html">第10部</a>)</li><li><strong>どの言語・エンジンでも「寿命のパターンを見つけて構造化する」のが本質</strong>で、道具(GC/RAII/プール)はその実装手段</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>「C++は手動メモリ管理」という表現のどこが不正確ですか。</li><li>C#とC++で「参照を持つ」の意味はどう違いますか。</li><li>両言語のリークの典型形を1つずつ挙げてください。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><a href="/study/runtime/memory/exercises.html">第7部演習</a>の問4(当たり判定結果の一時データ)を、Unity C#で同じ問題を解く場合(List再利用/NativeArray+Temp)と対比しながら解いてください。「同じ問題に同じ答え(再利用)を出している」ことの確認が目的です。</p><hr><p>前: <a href="/study/languages/csharp/il2cpp.html">ネイティブビルドとIL2CPP</a> | <a href="/study/languages/csharp/">カテゴリ目次</a> | 次: <a href="/study/languages/csharp/exceptions-comparison.html">C++例外とC#例外</a></p>',18)])])}const u=a(s,[["render",n]]);export{g as __pageData,u as default};
